/**
 * Out-of-office windows, one per member per organization. Every read and write is filtered by `orgId`, so an absence set in one workspace never shows up in another.
 */
import { and, eq } from "drizzle-orm";
import { getDb, memberAbsences } from "@/server/db";
import { orgPredicate } from "./base-repository";
import { toMemberAbsence } from "./_mappers";
import type { OrgId, UserId } from "@/types/common";
import type { MemberAbsence } from "@/types/member";

/** The stored absence, whether or not it has ended — callers decide what "away" means. */
export async function findAbsence(
  orgId: OrgId,
  userId: UserId,
): Promise<MemberAbsence | null> {
  const row = getDb()
    .select()
    .from(memberAbsences)
    .where(
      and(
        orgPredicate(memberAbsences.orgId, orgId),
        eq(memberAbsences.userId, userId),
      ),
    )
    .get();
  return row ? toMemberAbsence(row) : null;
}

/** Setting an absence again replaces the previous one. */
export async function upsertAbsence(
  absence: MemberAbsence,
): Promise<MemberAbsence> {
  const values = {
    delegateUserId: absence.delegateUserId,
    startsAt: absence.startsAt,
    endsAt: absence.endsAt,
    note: absence.note,
  };

  const row = getDb()
    .insert(memberAbsences)
    .values({ orgId: absence.orgId, userId: absence.userId, ...values })
    .onConflictDoUpdate({
      target: [memberAbsences.orgId, memberAbsences.userId],
      set: values,
    })
    .returning()
    .get();

  return toMemberAbsence(row);
}

/** Deleting when nothing is stored is not an error. */
export async function deleteAbsence(
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  getDb()
    .delete(memberAbsences)
    .where(
      and(
        orgPredicate(memberAbsences.orgId, orgId),
        eq(memberAbsences.userId, userId),
      ),
    )
    .run();
}

/**
 * Keeps every absence in the org that named `delegateUserId` but takes the
 * delegate away, so nothing is ever redirected to someone who has left.
 */
export async function dropDelegations(
  orgId: OrgId,
  delegateUserId: UserId,
): Promise<void> {
  getDb()
    .update(memberAbsences)
    .set({ delegateUserId: null })
    .where(
      and(
        orgPredicate(memberAbsences.orgId, orgId),
        eq(memberAbsences.delegateUserId, delegateUserId),
      ),
    )
    .run();
}
