  if (delegateUserId !== null) {
    if (delegateUserId === input.userId) {
      throw new Error("A member cannot be their own delegate");
    }
    await requireActiveMember(input.orgId, delegateUserId);
  }

  return absenceRepo.upsertAbsence({
    orgId: input.orgId,
    userId: input.userId,
    delegateUserId,
    startsAt: input.startsAt,
    endsAt: input.endsAt,
    note: input.note ?? null,
  });
}

/** Clearing when nothing is set is fine. */
export async function clearAbsence(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<void> {
  assertOrgScope(actor, orgId);

  const member = await requireActiveMember(orgId, userId);
  assertMayManageAbsence(actor, member);

  await absenceRepo.deleteAbsence(orgId, userId);
}

/**
 * The stored absence for as long as it has not ended — one that has not
 * started yet is still returned — and `null` once it is over or none is set.
 */
export async function getAbsence(
  actor: Actor,
  orgId: OrgId,
  userId: UserId,
): Promise<MemberAbsence | null> {
  assertOrgScope(actor, orgId);

  const member = await requireActiveMember(orgId, userId);
  assertCan(actor, "member:read", memberResource(member));

  const absence = await absenceRepo.findAbsence(orgId, userId);
  if (absence === null) return null;
  return parseIso(absence.endsAt).getTime() > Date.now() ? absence : null;
}

/**
 * Who stands in for `userId` at the instant `at`: the delegate named on their
 * absence, provided the absence applies at `at` and that delegate is still an
 * active member. `null` means work for `userId` stays with `userId`.
 *
 * One hop only — whether the delegate is away as well is deliberately never
 * asked, so delegation cannot chain.
 */
export async function activeDelegateOf(
  orgId: OrgId,
  userId: UserId,
  at: Date,
): Promise<UserId | null> {
  const absence = await absenceRepo.findAbsence(orgId, userId);
  if (absence === null || absence.delegateUserId === null) return null;
  if (!isWithinWindow(absence.startsAt, absence.endsAt, at)) return null;

  const delegate = await memberRepo.findMember(orgId, absence.delegateUserId);
  return delegate !== null && delegate.status === "active"
    ? delegate.userId
    : null;
}

/** A removed, suspended or foreign user is "not found" as far as absences go. */
async function requireActiveMember(
  orgId: OrgId,
  userId: UserId,
): Promise<Member> {
  const member = await memberRepo.findMember(orgId, userId);
  return requireFound(
    member !== null && member.status === "active" ? member : null,
    "Member",
    userId,
  );
}

/** Your own absence is yours to manage; anyone else's needs role-change rights. */
function assertMayManageAbsence(actor: Actor, member: Member): void {
  if (member.userId === actor.userId) return;
  assertCan(actor, "member:update_role", memberResource(member));
}

