/**
 * Out-of-office absences: who may set them, what is stored, when they count,
 * and what happens to them when a member leaves.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { PermissionDeniedError } from "@/lib/permissions";
import { TenantScopeError } from "@/lib/tenant";
import * as absenceRepo from "@/server/repositories/absence-repository";
import * as memberRepo from "@/server/repositories/member-repository";
import * as issueService from "@/server/services/issue-service";
import * as memberService from "@/server/services/member-service";
import { NotFoundError } from "@/server/services/_support";
import { toIsoTimestamp } from "@/types/common";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { SetAbsenceInput } from "@/schemas/member";
import type { UserId } from "@/types/common";
import type { Role } from "@/types/member";

const HOUR = 60 * 60 * 1000;

let cleanup: () => void;

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
});

afterEach(() => {
  vi.useRealTimers();
});

afterAll(() => {
  cleanup();
});

function at(offsetMs: number) {
  return toIsoTimestamp(new Date(Date.now() + offsetMs));
}

function absenceInput(
  tenant: Tenant,
  who: Role,
  overrides: Partial<SetAbsenceInput> = {},
): SetAbsenceInput {
  return {
    orgId: tenant.org.id,
    userId: tenant.userIds[who],
    delegateUserId: null,
    startsAt: at(-HOUR),
    endsAt: at(HOUR),
    note: null,
    ...overrides,
  };
}

describe("services/member-service — absences", () => {
  it("stores what was given and returns exactly that", async () => {
    const tenant = await createTenant("absence-store");
    const input = absenceInput(tenant, "member", {
      delegateUserId: tenant.userIds.admin,
      note: "Back on Monday",
    });

    const stored = await memberService.setAbsence(tenant.actors.member, input);

    expect(stored).toEqual(input);
    expect(
      await memberService.getAbsence(tenant.actors.viewer, tenant.org.id, tenant.userIds.member),
    ).toEqual(stored);
  });

  it("replaces an absence that is set again, and clears it on request", async () => {
    const tenant = await createTenant("absence-replace");
    await memberService.setAbsence(
      tenant.actors.member,
      absenceInput(tenant, "member", { delegateUserId: tenant.userIds.admin, note: "first" }),
    );

    const second = await memberService.setAbsence(
      tenant.actors.member,
      absenceInput(tenant, "member", { note: "second" }),
    );
    expect(second.delegateUserId).toBeNull();
    expect(
      await memberService.getAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.member),
    ).toEqual(second);

    await memberService.clearAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.member);
    expect(
      await memberService.getAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.member),
    ).toBeNull();

    // Nothing left to clear is not an error.
    await expect(
      memberService.clearAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.member),
    ).resolves.toBeUndefined();
  });

  it("returns a scheduled absence, and null once it has ended", async () => {
    const tenant = await createTenant("absence-read");
    const startsAt = at(2 * HOUR);
    const endsAt = at(4 * HOUR);
    await memberService.setAbsence(
      tenant.actors.member,
      absenceInput(tenant, "member", { startsAt, endsAt }),
    );
    const read = () =>
      memberService.getAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.member);

    expect(await read()).toMatchObject({ startsAt, endsAt });

    vi.useFakeTimers({ toFake: ["Date"] });
    vi.setSystemTime(new Date(endsAt).getTime() - 1);
    expect(await read()).not.toBeNull();

    vi.setSystemTime(new Date(endsAt));
    expect(await read()).toBeNull();
  });

  it("rejects an absence that does not end after it starts", async () => {
    const tenant = await createTenant("absence-order");
    const instant = at(HOUR);

    await expect(
      memberService.setAbsence(
        tenant.actors.member,
        absenceInput(tenant, "member", { startsAt: instant, endsAt: instant }),
      ),
    ).rejects.toThrow();
    await expect(
      memberService.setAbsence(
        tenant.actors.member,
        absenceInput(tenant, "member", { startsAt: at(2 * HOUR), endsAt: at(HOUR) }),
      ),
    ).rejects.toThrow();
    expect(await absenceRepo.findAbsence(tenant.org.id, tenant.userIds.member)).toBeNull();
  });

  it("rejects naming yourself as your own delegate", async () => {
    const tenant = await createTenant("absence-self-delegate");

    const attempt = memberService.setAbsence(
      tenant.actors.member,
      absenceInput(tenant, "member", { delegateUserId: tenant.userIds.member }),
    );

    await expect(attempt).rejects.toThrow();
    await expect(attempt).rejects.not.toBeInstanceOf(NotFoundError);
  });

  it("only accepts active members of the workspace as member or delegate", async () => {
    const tenant = await createTenant("absence-active");
    const other = await createTenant("absence-active-other");
    const viewer = await memberRepo.findMember(tenant.org.id, tenant.userIds.viewer);
    if (!viewer) throw new Error("fixture member missing");
    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: viewer.id,
    });

    // The delegate has left.
    await expect(
      memberService.setAbsence(
        tenant.actors.member,
        absenceInput(tenant, "member", { delegateUserId: tenant.userIds.viewer }),
      ),
    ).rejects.toBeInstanceOf(NotFoundError);
    // The delegate belongs to another workspace.
    await expect(
      memberService.setAbsence(
        tenant.actors.member,
        absenceInput(tenant, "member", { delegateUserId: other.userIds.admin }),
      ),
    ).rejects.toBeInstanceOf(NotFoundError);
    // The member has left.
    await expect(
      memberService.setAbsence(
        tenant.actors.owner,
        absenceInput(tenant, "viewer"),
      ),
    ).rejects.toBeInstanceOf(NotFoundError);
    // The member is somebody else's.
    await expect(
      memberService.setAbsence(
        tenant.actors.owner,
        absenceInput(tenant, "member", { userId: other.userIds.member }),
      ),
    ).rejects.toBeInstanceOf(NotFoundError);

    await expect(
      memberService.getAbsence(tenant.actors.owner, tenant.org.id, tenant.userIds.viewer),
    ).rejects.toBeInstanceOf(NotFoundError);
    await expect(
      memberService.clearAbsence(tenant.actors.owner, tenant.org.id, tenant.userIds.viewer),
    ).rejects.toBeInstanceOf(NotFoundError);
  });

  it("lets anyone manage their own absence but only role managers manage others'", async () => {
    const tenant = await createTenant("absence-permissions");

    for (const role of ["viewer", "member", "admin", "owner"] as const) {
      await expect(
        memberService.setAbsence(tenant.actors[role], absenceInput(tenant, role)),
      ).resolves.toMatchObject({ userId: tenant.userIds[role] });
    }

    await expect(
      memberService.setAbsence(tenant.actors.member, absenceInput(tenant, "viewer")),
    ).rejects.toBeInstanceOf(PermissionDeniedError);
    await expect(
      memberService.clearAbsence(tenant.actors.member, tenant.org.id, tenant.userIds.viewer),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await expect(
      memberService.setAbsence(tenant.actors.admin, absenceInput(tenant, "viewer", { note: "by admin" })),
    ).resolves.toMatchObject({ note: "by admin" });
    await expect(
      memberService.clearAbsence(tenant.actors.admin, tenant.org.id, tenant.userIds.member),
    ).resolves.toBeUndefined();
    expect(await absenceRepo.findAbsence(tenant.org.id, tenant.userIds.member)).toBeNull();
  });

  it("lets any member of the workspace look an absence up", async () => {
    const tenant = await createTenant("absence-lookup");
    await memberService.setAbsence(tenant.actors.member, absenceInput(tenant, "member"));

    for (const role of ["viewer", "member", "admin", "owner"] as const) {
      expect(
        await memberService.getAbsence(tenant.actors[role], tenant.org.id, tenant.userIds.member),
      ).not.toBeNull();
    }
  });

  it("refuses an orgId outside the actor's workspace on every operation", async () => {
    const tenant = await createTenant("absence-scope");
    const other = await createTenant("absence-scope-other");

    await expect(
      memberService.setAbsence(other.actors.owner, absenceInput(tenant, "member")),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      memberService.clearAbsence(other.actors.owner, tenant.org.id, tenant.userIds.member),
    ).rejects.toBeInstanceOf(TenantScopeError);
    await expect(
      memberService.getAbsence(other.actors.owner, tenant.org.id, tenant.userIds.member),
    ).rejects.toBeInstanceOf(TenantScopeError);
  });

  it("drops the absence of a member who is removed", async () => {
    const tenant = await createTenant("absence-removed");
    await memberService.setAbsence(tenant.actors.member, absenceInput(tenant, "member"));
    const member = await memberRepo.findMember(tenant.org.id, tenant.userIds.member);
    if (!member) throw new Error("fixture member missing");

    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: member.id,
    });

    expect(await absenceRepo.findAbsence(tenant.org.id, tenant.userIds.member)).toBeNull();
  });

  it("keeps an absence but drops the delegate when the delegate is removed", async () => {
    const tenant = await createTenant("absence-delegate-removed");
    const stored = await memberService.setAbsence(
      tenant.actors.member,
      absenceInput(tenant, "member", { delegateUserId: tenant.userIds.admin, note: "away" }),
    );
    const bystander = await memberService.setAbsence(
      tenant.actors.viewer,
      absenceInput(tenant, "viewer", { delegateUserId: tenant.userIds.owner }),
    );
    const admin = await memberRepo.findMember(tenant.org.id, tenant.userIds.admin);
    if (!admin) throw new Error("fixture member missing");

    await memberService.removeMember(tenant.actors.owner, {
      orgId: tenant.org.id,
      memberId: admin.id,
    });

    expect(
      await memberService.getAbsence(tenant.actors.owner, tenant.org.id, tenant.userIds.member),
    ).toEqual({ ...stored, delegateUserId: null });
    expect(
      await memberService.getAbsence(tenant.actors.owner, tenant.org.id, tenant.userIds.viewer),
    ).toEqual(bystander);

    // Nothing is redirected to the member who left.
    const issue = await issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, { assigneeId: tenant.userIds.member }),
    );
    expect(issue.assigneeId).toBe(tenant.userIds.member);
  });

  it("keeps workspaces independent for a user who belongs to both", async () => {
    const north = await createTenant("absence-north");
    const south = await createTenant("absence-south");
    const shared: UserId = north.userIds.member;
    await memberRepo.insertMember(south.org.id, shared, "member", null);

    await memberService.setAbsence(
      north.actors.member,
      absenceInput(north, "member", { delegateUserId: north.userIds.admin }),
    );

    expect(await memberService.getAbsence(south.actors.owner, south.org.id, shared)).toBeNull();
    const southIssue = await issueService.createIssue(
      south.actors.owner,
      issueInput(south.org.id, south.project.id, { assigneeId: shared }),
    );
    expect(southIssue.assigneeId).toBe(shared);

    const northIssue = await issueService.createIssue(
      north.actors.owner,
      issueInput(north.org.id, north.project.id, { assigneeId: shared }),
    );
    expect(northIssue.assigneeId).toBe(north.userIds.admin);
  });
});
