/**
 * While a member is away, assignments, overdue alerts and mention alerts for
 * them reach their delegate. "Away" is decided at the moment of the action.
 */
import { afterAll, afterEach, beforeAll, describe, expect, it, vi } from "vitest";

vi.mock("@/lib/id", () => import("../server/_support/doubles/id"));
vi.mock("@/lib/logger", async () => (await import("../server/_support/doubles/misc")).loggerModule);

import { emit, subscribe } from "@/lib/event-bus";
import { PermissionDeniedError } from "@/lib/permissions";
import { resetOverdueTracking, runOverdueIssueJob } from "@/server/jobs/overdue-issue-job";
import * as activityRepo from "@/server/repositories/activity-repository";
import * as preferenceRepo from "@/server/repositories/notification-preference-repository";
import * as usageRepo from "@/server/repositories/usage-repository";
import * as issueService from "@/server/services/issue-service";
import * as memberService from "@/server/services/member-service";
import { listNotifications } from "@/server/services/notification-service";
import { registerActivityListeners } from "@/server/services/activity-service";
import { toIsoTimestamp } from "@/types/common";
import { createTenant, issueInput, useTemporaryDatabase } from "../server/_support/fixtures";
import type { Tenant } from "../server/_support/fixtures";
import type { CommentId, IsoTimestamp, UserId } from "@/types/common";
import type { NotificationKind } from "@/types/notification";
import type { Role } from "@/types/member";
import type { TaskflowEventMap, TaskflowEventType, Unsubscribe } from "@/types/event";

const HOUR = 60 * 60 * 1000;

let cleanup: () => void;
const detachers: Unsubscribe[] = [];

beforeAll(async () => {
  cleanup = await useTemporaryDatabase();
  detachers.push(registerActivityListeners());
});

afterEach(() => {
  vi.useRealTimers();
});

afterAll(() => {
  while (detachers.length > 0) detachers.pop()?.();
  cleanup();
});

function at(offsetMs: number): IsoTimestamp {
  return toIsoTimestamp(new Date(Date.now() + offsetMs));
}

/** `who` goes away around the current instant, optionally naming a stand-in. */
async function goAway(
  tenant: Tenant,
  who: Role,
  delegate: Role | null,
  window: { startsAt?: IsoTimestamp; endsAt?: IsoTimestamp } = {},
) {
  return memberService.setAbsence(tenant.actors[who], {
    orgId: tenant.org.id,
    userId: tenant.userIds[who],
    delegateUserId: delegate === null ? null : tenant.userIds[delegate],
    startsAt: window.startsAt ?? at(-HOUR),
    endsAt: window.endsAt ?? at(HOUR),
    note: null,
  });
}

async function alertsFor(tenant: Tenant, userId: UserId, kind: NotificationKind) {
  const page = await listNotifications(tenant.actors.owner, {
    orgId: tenant.org.id,
    recipientId: userId,
    unreadOnly: false,
    kind: [kind],
    limit: 25,
    cursor: null,
  });
  return page.items;
}

function capture<K extends TaskflowEventType>(type: K): TaskflowEventMap[K][] {
  const seen: TaskflowEventMap[K][] = [];
  detachers.push(
    subscribe(type, (payload) => {
      seen.push(payload);
    }),
  );
  return seen;
}

async function newIssue(tenant: Tenant, assignee: Role | null = null) {
  return issueService.createIssue(
    tenant.actors.owner,
    issueInput(tenant.org.id, tenant.project.id, {
      assigneeId: assignee === null ? null : tenant.userIds[assignee],
    }),
  );
}

async function assign(tenant: Tenant, actor: Role, issueId: string, assignee: Role) {
  return issueService.assignIssue(tenant.actors[actor], {
    orgId: tenant.org.id,
    issueId: issueId as never,
    assigneeId: tenant.userIds[assignee],
  });
}

describe("assignments while the assignee is away", () => {
  it("hands an assignment to the delegate in every respect", async () => {
    const tenant = await createTenant("deleg-assign");
    await goAway(tenant, "member", "admin");
    const issue = await newIssue(tenant);
    const assigned = capture("issue.assigned");

    const after = await assign(tenant, "owner", issue.id, "member");

    expect(after.assigneeId).toBe(tenant.userIds.admin);
    expect(assigned).toHaveLength(1);
    expect(assigned[0]).toMatchObject({
      issueId: issue.id,
      assigneeId: tenant.userIds.admin,
      previousAssigneeId: null,
    });

    const audit = await activityRepo.listActivity({
      orgId: tenant.org.id,
      limit: 50,
      cursor: null,
    });
    const entry = audit.items.find(
      (event) => event.action === "issue.assigned" && event.subjectId === issue.id,
    );
    expect(entry?.summary).toBe(`Assigned to ${tenant.userIds.admin}`);

    expect(await alertsFor(tenant, tenant.userIds.admin, "issue_assigned")).toHaveLength(1);
    expect(await alertsFor(tenant, tenant.userIds.member, "issue_assigned")).toHaveLength(0);
  });

  it("makes the delegate the issue's assignee for permission purposes", async () => {
    const tenant = await createTenant("deleg-permission");
    await goAway(tenant, "member", "viewer");
    const issue = await newIssue(tenant);
    await assign(tenant, "owner", issue.id, "member");

    // A viewer may only update an issue they are assigned.
    await expect(
      issueService.updateIssue(tenant.actors.viewer, {
        orgId: tenant.org.id,
        issueId: issue.id,
        title: "Retitled by the delegate",
      }),
    ).resolves.toMatchObject({ title: "Retitled by the delegate" });
  });

  it("redirects an issue created with the away member as its assignee", async () => {
    const tenant = await createTenant("deleg-create");
    await goAway(tenant, "member", "admin");
    const created = capture("issue.created");

    const issue = await newIssue(tenant, "member");

    expect(issue.assigneeId).toBe(tenant.userIds.admin);
    expect(created[0]).toMatchObject({ assigneeId: tenant.userIds.admin });
  });

  it("never redirects an issue the away member takes themselves", async () => {
    const tenant = await createTenant("deleg-take");
    await goAway(tenant, "member", "admin");
    const issue = await newIssue(tenant);

    const taken = await assign(tenant, "member", issue.id, "member");
    expect(taken.assigneeId).toBe(tenant.userIds.member);

    const created = await issueService.createIssue(
      tenant.actors.member,
      issueInput(tenant.org.id, tenant.project.id, { assigneeId: tenant.userIds.member }),
    );
    expect(created.assigneeId).toBe(tenant.userIds.member);
  });

  it("does not chain when the delegate is away as well", async () => {
    const tenant = await createTenant("deleg-chain");
    await goAway(tenant, "member", "admin");
    await goAway(tenant, "admin", "viewer");
    const issue = await newIssue(tenant);

    const after = await assign(tenant, "owner", issue.id, "member");

    expect(after.assigneeId).toBe(tenant.userIds.admin);
    expect(await alertsFor(tenant, tenant.userIds.viewer, "issue_assigned")).toHaveLength(0);
  });

  it("assigns as usual when no delegate is named", async () => {
    const tenant = await createTenant("deleg-none");
    await goAway(tenant, "member", null);
    const issue = await newIssue(tenant);

    const after = await assign(tenant, "owner", issue.id, "member");

    expect(after.assigneeId).toBe(tenant.userIds.member);
    expect(await alertsFor(tenant, tenant.userIds.member, "issue_assigned")).toHaveLength(1);
  });

  it("leaves issues that were already the member's alone", async () => {
    const tenant = await createTenant("deleg-existing");
    const issue = await newIssue(tenant, "member");

    await goAway(tenant, "member", "admin");

    const found = await issueService.getIssue(tenant.actors.owner, tenant.org.id, issue.id);
    expect(found.issue.assigneeId).toBe(tenant.userIds.member);
  });

  it("counts the start but not the end, and stops applying once it is over", async () => {
    const tenant = await createTenant("deleg-window");
    const startsAt = at(2 * HOUR);
    const endsAt = at(4 * HOUR);
    await goAway(tenant, "member", "admin", { startsAt, endsAt });
    const issue = await newIssue(tenant);
    vi.useFakeTimers({ toFake: ["Date"] });

    vi.setSystemTime(new Date(startsAt).getTime() - 1);
    expect((await assign(tenant, "owner", issue.id, "member")).assigneeId).toBe(
      tenant.userIds.member,
    );

    vi.setSystemTime(new Date(startsAt));
    expect((await assign(tenant, "owner", issue.id, "member")).assigneeId).toBe(
      tenant.userIds.admin,
    );

    vi.setSystemTime(new Date(endsAt).getTime() - 1);
    expect((await assign(tenant, "owner", issue.id, "member")).assigneeId).toBe(
      tenant.userIds.admin,
    );

    vi.setSystemTime(new Date(endsAt));
    expect((await assign(tenant, "owner", issue.id, "member")).assigneeId).toBe(
      tenant.userIds.member,
    );
  });

  it("keeps the assign permission check ahead of any redirect", async () => {
    const tenant = await createTenant("deleg-denied");
    await goAway(tenant, "member", "admin");
    const issue = await newIssue(tenant);

    await expect(assign(tenant, "viewer", issue.id, "member")).rejects.toBeInstanceOf(
      PermissionDeniedError,
    );
  });
});

describe("overdue alerts while the assignee is away", () => {
  const NOW = new Date("2026-06-01T07:00:00.000Z");
  const PAST = "2026-01-01T00:00:00.000Z";

  async function overdueTenant(slug: string) {
    resetOverdueTracking();
    const tenant = await createTenant(slug);
    await usageRepo.recomputeUsage(tenant.org.id);
    return tenant;
  }

  async function overdueIssue(tenant: Tenant, assignee: Role) {
    return issueService.createIssue(
      tenant.actors.owner,
      issueInput(tenant.org.id, tenant.project.id, {
        assigneeId: tenant.userIds[assignee],
        dueAt: PAST,
      }),
    );
  }

  const window = {
    startsAt: toIsoTimestamp(new Date(NOW.getTime() - HOUR)),
    endsAt: toIsoTimestamp(new Date(NOW.getTime() + HOUR)),
  };

  it("alerts the delegate instead of the assignee", async () => {
    const tenant = await overdueTenant("overdue-away");
    const issue = await overdueIssue(tenant, "member");
    await goAway(tenant, "member", "admin", window);
    const overdue = capture("issue.overdue");

    await runOverdueIssueJob(NOW);

    expect(overdue.filter((event) => event.issueId === issue.id)).toHaveLength(1);
    expect(await alertsFor(tenant, tenant.userIds.admin, "issue_overdue")).toHaveLength(1);
    expect(await alertsFor(tenant, tenant.userIds.member, "issue_overdue")).toHaveLength(0);
  });

  it("alerts the assignee when there is no delegate", async () => {
    const tenant = await overdueTenant("overdue-nodelegate");
    await overdueIssue(tenant, "member");
    await goAway(tenant, "member", null, window);

    await runOverdueIssueJob(NOW);

    expect(await alertsFor(tenant, tenant.userIds.member, "issue_overdue")).toHaveLength(1);
  });

  it("alerts the assignee when the absence has not started or has ended by the sweep", async () => {
    const tenant = await overdueTenant("overdue-outside");
    await overdueIssue(tenant, "member");
    await goAway(tenant, "member", "admin", {
      startsAt: toIsoTimestamp(new Date(NOW.getTime() + HOUR)),
      endsAt: toIsoTimestamp(new Date(NOW.getTime() + 2 * HOUR)),
    });

    await runOverdueIssueJob(NOW);

    expect(await alertsFor(tenant, tenant.userIds.member, "issue_overdue")).toHaveLength(1);
    expect(await alertsFor(tenant, tenant.userIds.admin, "issue_overdue")).toHaveLength(0);
  });

  it("treats the end of the absence as already over", async () => {
    const tenant = await overdueTenant("overdue-end");
    await overdueIssue(tenant, "member");
    await goAway(tenant, "member", "admin", {
      startsAt: toIsoTimestamp(new Date(NOW.getTime() - HOUR)),
      endsAt: toIsoTimestamp(NOW),
    });

    await runOverdueIssueJob(NOW);

    expect(await alertsFor(tenant, tenant.userIds.member, "issue_overdue")).toHaveLength(1);
  });
});

